CREATE FUNCTION public.finance_source_operation_undo(p_operation uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.finance_source_operations%ROWTYPE;j public.journal_entries%ROWTYPE;r uuid;n uuid;u uuid;d date;BEGIN
SELECT * INTO o FROM public.finance_source_operations WHERE id=p_operation FOR UPDATE;SELECT * INTO j FROM public.journal_entries WHERE id=o.original_entry_id;
IF NOT FOUND OR NOT public.user_has_tenant(auth.uid(),o.tenant_id) OR NOT(public.has_role(auth.uid(),'admin') OR public.is_tenant_admin(o.tenant_id,auth.uid())) OR (j.venue_id IS NOT NULL AND NOT public.user_has_venue(auth.uid(),j.venue_id)) THEN RAISE EXCEPTION 'Finance access required';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('finance-period:'||o.tenant_id::text,0));
IF o.undone_by IS NOT NULL OR EXISTS(SELECT 1 FROM public.finance_source_operations WHERE original_entry_id=o.replacement_entry_id) OR (o.source_posting_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.finance_source_postings WHERE id=o.source_posting_id AND current_entry_id=coalesce(o.replacement_entry_id,o.reversal_entry_id))) THEN RAISE EXCEPTION 'Correction changed; Undo is no longer safe';END IF;
d:=j.entry_date;IF EXISTS(SELECT 1 FROM public.finance_closed_periods WHERE tenant_id=o.tenant_id AND reopened_at IS NULL AND month_start=date_trunc('month',d)::date) THEN d:=(now() AT TIME ZONE 'Asia/Hong_Kong')::date;END IF;PERFORM public.finance_assert_open(o.tenant_id,d);
INSERT INTO public.journal_entries(tenant_id,entry_date,memo,source_type,source_id,venue,venue_id,status,created_by,manually_adjusted) VALUES(o.tenant_id,d,'Undo · '||o.reason,'adjustment','source_undo:'||o.id,j.venue,j.venue_id,'draft',auth.uid(),true) RETURNING id INTO r;
INSERT INTO public.journal_lines(tenant_id,entry_id,account_id,debit,credit,venue,venue_id,line_no,memo,mapping_status) SELECT tenant_id,r,account_id,credit,debit,venue,venue_id,line_no,'Undo reversal','mapped' FROM public.journal_lines WHERE entry_id=o.reversal_entry_id;
UPDATE public.journal_entries SET status='posted',posted_at=now() WHERE id=r;
IF o.replacement_entry_id IS NOT NULL THEN
SELECT * INTO j FROM public.journal_entries WHERE id=o.replacement_entry_id;d:=j.entry_date;IF EXISTS(SELECT 1 FROM public.finance_closed_periods WHERE tenant_id=o.tenant_id AND reopened_at IS NULL AND month_start=date_trunc('month',d)::date) THEN d:=(now() AT TIME ZONE 'Asia/Hong_Kong')::date;END IF;PERFORM public.finance_assert_open(o.tenant_id,d);
INSERT INTO public.journal_entries(tenant_id,entry_date,memo,source_type,source_id,venue,venue_id,status,created_by,manually_adjusted) VALUES(o.tenant_id,d,'Undo replacement · '||o.reason,'adjustment','source_undo_replace:'||o.id,j.venue,j.venue_id,'draft',auth.uid(),true) RETURNING id INTO n;
INSERT INTO public.journal_lines(tenant_id,entry_id,account_id,debit,credit,venue,venue_id,line_no,memo,mapping_status) SELECT tenant_id,n,account_id,credit,debit,venue,venue_id,line_no,'Undo replacement','mapped' FROM public.journal_lines WHERE entry_id=o.replacement_entry_id;UPDATE public.journal_entries SET status='posted',posted_at=now() WHERE id=n;END IF;
INSERT INTO public.finance_source_operations(tenant_id,source_posting_id,original_entry_id,reversal_entry_id,replacement_entry_id,actor_id,reason,before_snapshot,after_snapshot) VALUES(o.tenant_id,o.source_posting_id,o.reversal_entry_id,r,n,auth.uid(),'Undo · '||o.reason,o.after_snapshot,o.before_snapshot) RETURNING id INTO u;
UPDATE public.finance_source_operations SET undone_by=u WHERE id=o.id;IF o.source_posting_id IS NOT NULL THEN UPDATE public.finance_source_postings SET current_entry_id=r,source_snapshot=o.before_snapshot,revision=revision+1 WHERE id=o.source_posting_id;END IF;
INSERT INTO public.audit_log(tenant_id,user_id,action,entity_type,entity_id,details) VALUES(o.tenant_id,auth.uid(),'source_books_undo','finance_source_operations',o.id::text,jsonb_build_object('undo_operation',u,'reason',o.reason));RETURN u;END $$;
REVOKE ALL ON FUNCTION public.finance_source_operation_undo(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_source_operation_undo(uuid) TO authenticated;
CREATE FUNCTION public.finance_invoice_date_sync() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j uuid;BEGIN
IF OLD.invoice_date IS NOT DISTINCT FROM NEW.invoice_date THEN RETURN NEW;END IF;
IF OLD.venue IS DISTINCT FROM NEW.venue OR OLD.total_amount IS DISTINCT FROM NEW.total_amount THEN RAISE EXCEPTION 'Date plus amount or venue change requires a full source correction';END IF;
SELECT p.current_entry_id INTO j FROM public.finance_source_postings p WHERE p.tenant_id=NEW.tenant_id AND p.source_type='invoice' AND p.source_record_id=NEW.id FOR UPDATE;
IF j IS NOT NULL THEN PERFORM public.finance_source_date_correct(j,NEW.invoice_date,'Edited by '||auth.uid()||' · date '||OLD.invoice_date||' → '||NEW.invoice_date||' · books updated',public.finance_source_snapshot(j),false);END IF;RETURN NEW;END $$;
CREATE TRIGGER zz_finance_invoice_date_sync AFTER UPDATE OF invoice_date ON public.invoices FOR EACH ROW EXECUTE FUNCTION public.finance_invoice_date_sync();
CREATE FUNCTION public.finance_source_drift_count(p_tenant uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN jsonb_build_object('invoice_drift',jsonb_array_length(public.finance_source_drift(p_tenant)),'unresolved_sales_sources',(SELECT count(*) FROM public.finance_source_postings p JOIN public.journal_entries j ON j.id=p.current_entry_id WHERE p.tenant_id=p_tenant AND p.source_type='sales_summary' AND j.source_type='sales_summary' AND NOT EXISTS(SELECT 1 FROM public.sales_records s WHERE s.tenant_id=p_tenant AND s.date||'__'||s.venue=p.source_key)));END $$;
REVOKE ALL ON FUNCTION public.finance_source_drift_count(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_source_drift_count(uuid) TO authenticated;